def get_all_sessions() -> List[Dict[str, Any]]:
    """Return every normal gym workout session."""
    return NORMAL_GYM_CATALOG


def get_categories() -> List[str]:
    """Return all available top-level gym categories."""
    return sorted({session["category"] for session in NORMAL_GYM_CATALOG})


def get_subcategories(category: Optional[str] = None) -> List[str]:
    """Return subcategories, optionally filtered by category."""
    sessions = NORMAL_GYM_CATALOG
    if category is not None:
        category_norm = category.strip().lower()
        sessions = [s for s in sessions if s["category"].strip().lower() == category_norm]
    return sorted({session["subcategory"] for session in sessions})


def get_sessions(category: Optional[str] = None, subcategory: Optional[str] = None) -> List[Dict[str, Any]]:
    """Return sessions filtered by category and/or subcategory."""
    sessions = NORMAL_GYM_CATALOG
    if category is not None:
        category_norm = category.strip().lower()
        sessions = [s for s in sessions if s["category"].strip().lower() == category_norm]
    if subcategory is not None:
        subcategory_norm = subcategory.strip().lower()
        sessions = [s for s in sessions if s["subcategory"].strip().lower() == subcategory_norm]
    return sessions


def get_session_by_id(session_id: str) -> Optional[Dict[str, Any]]:
    """Return one session by its stable id, or None if not found."""
    for session in NORMAL_GYM_CATALOG:
        if session["id"] == session_id:
            return session
    return None


def search_sessions(query: str) -> List[Dict[str, Any]]:
    """Search category, subcategory, workout name, notes, and exercise names."""
    q = query.strip().lower()
    if not q:
        return []
    results: List[Dict[str, Any]] = []
    for session in NORMAL_GYM_CATALOG:
        haystack = " ".join([
            session.get("category", ""),
            session.get("subcategory", ""),
            session.get("workout_name", ""),
            " ".join(session.get("notes", [])),
            " ".join(ex.get("name", "") for ex in session.get("exercises", [])),
        ]).lower()
        if q in haystack:
            results.append(session)
    return results


CATALOG_METADATA: Dict[str, Any] = {
    "source_file": "Texto colado.txt",
    "session_count": len(NORMAL_GYM_CATALOG),
    "exercise_count": sum(len(session.get("exercises", [])) for session in NORMAL_GYM_CATALOG),
    "duplicate_sessions_removed": 117,
    "categories": get_categories(),
}


__all__ = [
    "NORMAL_GYM_CATALOG",
    "CATALOG_METADATA",
    "get_all_sessions",
    "get_categories",
    "get_subcategories",
    "get_sessions",
    "get_session_by_id",
    "search_sessions",
]
